    readonly activeAutomationNamesByRefName?: ReadonlyMap<string, string>;
    /** Sole on-demand record parameter targeting this same owner, keyed by automation refName, for CURRENT_RECORD widget binding. */
    readonly onDemandRecordParamByAutomationRefName?: ReadonlyMap<string, string>;
    /** Terraform labels of datamines managed by a table in this workspace. */
    readonly managedDatamineLabels?: ReadonlySet<string>;
